// `@cavea/renderer`: the buyer-facing seat map (docs/05-web-sdk.md). The WASM
// under ../wasm is generated by `cargo xtask build-web` and is not checked in.
// Importing this module touches no browser global.
import { version } from "../wasm/cavea_web.js";
import { browserEnv, loadWasm } from "./browser.ts";
import { CaveaError } from "./errors.ts";
import type { SeatMapOptions } from "./options.ts";
import { createMap, type SeatMap } from "./seatmap.ts";

export {
  customState,
  staticState,
  type AdapterContext,
  type ChartSource,
  type HoldRefusal,
  type HoldResult,
  type LabelDelta,
  type Snapshot,
  type StateAdapter,
} from "./adapter.ts";
export { CaveaError, type CaveaErrorCode } from "./errors.ts";
export type { GestureHandling } from "./host.ts";
export type {
  ReadyInfo,
  SeatMapOptions,
  SeatObject,
  Selection,
  Theme,
  ThemeName,
} from "./options.ts";
export type { SeatMap } from "./seatmap.ts";

/**
 * Draws a seat map in `element` (in a shadow root, filling the element) and
 * resolves at chart-ready: the chart drawn and the first state applied.
 * Rejects with a fatal `CaveaError` when the options are invalid, outside a
 * browser, without WebAssembly or WebGL2, or when the chart or the adapter's
 * first state cannot be had. After it resolves, nothing throws into the page:
 * errors go to `onError`.
 */
export function createSeatMap(element: HTMLElement, options?: SeatMapOptions): Promise<SeatMap> {
  if (typeof window === "undefined" || typeof document === "undefined") {
    return Promise.reject(
      new CaveaError("not_browser", "createSeatMap needs a browser (window and document)", true),
    );
  }
  return createMap(browserEnv(), element, options);
}

/** Loads the shared WASM (as `createSeatMap` does) and reports its version. */
export async function loadRenderer(): Promise<{ version(): string }> {
  await loadWasm();
  return { version };
}
